mapper.select:

where doc_id = #{docId}

    and (content like concat('%', #{keyword}, '%') or article_no like concat('%', #{keyword}, '%'))

order by id asc

mapper.update:
update law_knowledge_chunk
set embedding_json  = #{embeddingJson},
    embedding_model = #{embeddingModel}
where id = #{id}

mapper.select:
select c.id, c.doc_id, c.article_no, c.content, c.keywords, c.token_count, c.embedding_json, c.embedding_model, c.create_time, d.title as doc_title from law_knowledge_chunk c inner join law_knowledge_doc d on d.id = c.doc_id where d.status = '0' and c.doc_id in
#{docId}
order by c.id asc
